Use [SalesforceMigration]
go

drop view if exists [sfrhd].[vw_upsert_PermissionSetLicense-ALL]
go

create view [sfrhd].[vw_upsert_PermissionSetLicense-ALL] as
with cte_User as (
    select
        [Id]
        ,[Metazoa_External_ID__c]
    from [SalesforceMigration].[sfrhd].[User] (nolock)
    where 1=1
    and [Metazoa_External_ID__c] is not null
    --and [Licensee__c] = 'Shadforth'
)
,cte_src as (
    select s.*
        ,[Id-tgt] = t.[Id]
    from [SalesforceMigration].[sf].[PermissionSetLicense] s (nolock)
    left join [SalesforceMigration].[sfrhd].[PermissionSetLicense] t (nolock)
        on t.[DeveloperName] = s.[DeveloperName]
    where 1=1
and t.[Id] is null
)
select -- top 1
    [Id] = coalesce(s.[Id-tgt],'')
    ,[Metazoa_External_ID__c] = s.[Id]
    ,s.[DeveloperName]
    ,s.[ExpirationDate]
    ,[IsAvailableForIntegrations] = iif(s.[IsAvailableForIntegrations] = 1, 'true', 'false')
    ,[IsSupplementLicense] = iif(s.[IsSupplementLicense] = 1, 'true', 'false')
    ,s.[Language]
    ,s.[LicenseExpirationPolicy]
    ,s.[MasterLabel]
    --,[MaximumPermissionsAccessActivation] = iif(s.[MaximumPermissionsAccessActivation] = 1, 'true', 'false')
    --,[MaximumPermissionsAccessCdpDataExplorer] = iif(s.[MaximumPermissionsAccessCdpDataExplorer] = 1, 'true', 'false')
